package utils

import "strings"

// ResolveLLMProviderForModel fills an omitted provider from the model family.
// GPT-family model IDs are routed through Azure OpenAI in this backend.
func ResolveLLMProviderForModel(provider, model string) string {
	if strings.TrimSpace(provider) != "" {
		return provider
	}
	if IsGPTFamilyModel(model) {
		return "Azure"
	}
	return provider
}

func IsGPTFamilyModel(model string) bool {
	baseModel := strings.ToLower(strings.TrimSpace(model))
	if separator := strings.Index(baseModel, "::"); separator > 0 {
		baseModel = baseModel[:separator]
	}
	return strings.HasPrefix(baseModel, "gpt-") ||
		strings.HasPrefix(baseModel, "chatgpt-") ||
		strings.HasPrefix(baseModel, "azuregpt-")
}
