// AIServiceConfig stores model-only settings alongside content prompts. Prompt
// text remains owned by the caller; aliases and provider fallbacks use the same
// resolver as marking, chat, and content generation.
func AIServiceConfig(db *gorm.DB, name, provider, model string) *models.ContentPromptConfig {
	return GetContentPromptOrDefault(db, name, models.ContentPromptConfig{
		Name: name, UserPrompt: "[DYNAMIC]", Company: provider, LLM: model,
		FallbackModels: datatypes.JSON(`[]`), IsActive: true,
	})
}
